def compute_stats(numbers):
    if not numbers:
        return {'count': 0, 'mean': 0.0, 'variance': 0.0, 'min': None, 'max': None}
    count = len(numbers)
    total = sum(numbers)
    mean = total / count
    variance = sum((n - mean) ** 2 for n in numbers) / count
    return {
        'count': count,
        'mean': mean,
        'variance': variance,
        'min': min(numbers),
        'max': max(numbers),
    }
